import * as C from './core.js';
const KEY='timegrove-save-v1',BACKUP=KEY+'-previous';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],icon=name=>`<i data-lucide="${name}"></i>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=C.initialState(),mode='study',minutes=25,page='village',village=null,drawBusy=false,historyLimit=30,broken=false,toastTimeout,readyNotified=false;
function icons(){window.lucide?.createIcons();}
function storageWarning(msg){$('#storage-alert').hidden=false;$('#storage-alert').textContent=msg;$('#save-state').textContent='存档需要处理';}
try{const saved=localStorage.getItem(KEY);if(saved)state=C.validateState(JSON.parse(saved));else localStorage.setItem(KEY,JSON.stringify(state));}catch(e){broken=true;storageWarning('无法读取或保存此设备的存档。请先导出备份或导入有效存档；当前操作已暂停，避免覆盖原有进度。');}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function transact(fn){const task=()=>{if(broken)throw Error('请先在「存档与规则」中导入有效存档');const saved=localStorage.getItem(KEY);const next=saved?C.validateState(JSON.parse(saved)):C.initialState();const result=fn(next);C.accrue(next);localStorage.setItem(KEY,JSON.stringify(next));state=next;render();return result;};try{return await(navigator.locks?.request?navigator.locks.request(KEY,task):Promise.resolve().then(task));}catch(e){toast(e.message||'操作未完成，进度没有改变');throw e;}}
function safe(fn){return (...args)=>{try{return Promise.resolve(fn(...args)).catch(()=>{});}catch{return undefined;}};}
const fmt=n=>Math.floor(n).toLocaleString('zh-CN');
function duration(s){const m=Math.floor(s/60);return m>=60?`${Math.floor(m/60)} 小时 ${m%60} 分钟`:`${m} 分钟`;}
function latest(){return state.sessions.filter(x=>x.kind==='study').sort((a,b)=>b.endedAt-a.endedAt)[0];}
function rewardText(r){return Object.entries(r).filter(([,v])=>v>0).map(([k,v])=>`+${Number(v.toFixed(1))} ${C.RESOURCES[k].name}`).join(' · ');}
function weekData(){const start=C.weekStart(),days=[];for(let i=0;i<7;i++){const d=new Date(start);d.setDate(d.getDate()+i);const end=new Date(d);end.setDate(end.getDate()+1);days.push({start:+d,seconds:C.secondsBetween(state,+d,+end)});}return days;}
function setPage(p){if(!['village','journal','collection'].includes(p))p='village';page=p;$$('.page').forEach(el=>{el.hidden=el.id!==`page-${p}`;el.classList.toggle('active',!el.hidden);});$$('.nav-item[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===p));const titles={village:['我的村庄','今天，也让村庄长大一点。','把时间留给热爱的事，剩下的交给生长。'],journal:['学习手记','认真度过的时间，都在这里。','不必每一天都完美，回头看看，你已经走了很远。'],collection:['奇物收藏','收集一小片世界的惊奇。','让每一段专注，成为值得珍藏的回忆。']};$('#page-label').textContent=titles[p][0];$('#page-title').textContent=titles[p][1];$('#page-subtitle').textContent=titles[p][2];if(location.hash!==`#${p}`)history.replaceState(null,'',`#${p}`);render();window.scrollTo({top:0,behavior:'instant'});}
function renderStats(){const days=weekData(),week=days.reduce((n,d)=>n+d.seconds,0),m=Math.floor(week/60),pop=C.population(state);$('#weekly-total').innerHTML=`${Math.floor(m/60)} <small>小时</small> ${String(m%60).padStart(2,'0')} <small>分</small>`;$('#population').innerHTML=`${pop} <small>位</small>`;$('#population-caption').textContent=`再学习 ${Math.ceil((3600-C.studySeconds(state)%3600)/60)} 分钟，迎来新邻居`;const built=Object.values(state.buildings).filter(Boolean).length;$('#village-progress').textContent=`${built} 座建筑 · ${pop} 位居民`;$('#village-level').textContent=pop>=20?'繁盛小镇':pop>=8?'成长村落':'初生聚落';const max=Math.max(3600,...days.map(x=>x.seconds));$('#mini-bars').innerHTML=days.map(x=>`<span style="height:${Math.max(12,x.seconds/max*100)}%"></span>`).join('');$('#resources').innerHTML=Object.entries(C.RESOURCES).map(([k,r])=>`<div class="resource-item">${icon(r.icon)}<span>${r.name}</span><strong>${fmt(state.resources[k])}</strong></div>`).join('');const last=latest();if(last){$('#last-caption').textContent=`上次：${last.topic}`;}else{$('#last-caption').textContent='第一段专注，正等着你';}updateLast();$('#week-caption').textContent=week?`本周 ${state.sessions.filter(x=>x.kind==='study'&&x.endedAt>=C.weekStart()).length} 次学习打卡`:'从本周一开始，慢慢积累';}
function updateLast(){const l=latest();if(!l){$('#last-study').textContent='尚未开始';return;}const diff=Math.max(0,Date.now()-l.endedAt),m=Math.floor(diff/60000);$('#last-study').textContent=m<1?'刚刚':m<60?`${m} 分钟`:m<1440?`${Math.floor(m/60)} 小时 ${m%60} 分`:`${Math.floor(m/1440)} 天 ${Math.floor(m%1440/60)} 小时`;}
function renderProduction(){const projected=structuredClone(state);C.accrue(projected);const total=Object.values(projected.pending).reduce((a,b)=>a+b,0);$('#harvest-label').textContent=total>=1?`领取产出 · ${fmt(total)}`:'正在积攒';$('#harvest-button').disabled=total<1||broken;$('#production-caption').textContent=Object.entries(C.rates(state)).filter(([,v])=>v).map(([k,v])=>`${C.RESOURCES[k].name} +${v}/h`).join(' · ');}
function renderTimer(){const t=state.timer;if(t){mode=t.kind;minutes=Math.ceil(t.goal/60);}$$('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===mode);b.setAttribute('aria-selected',String(b.dataset.mode===mode));b.disabled=!!t;});$('#durations').innerHTML=(mode==='study'?[25,45,60]:[5,10,15]).map(m=>`<button data-minutes="${m}" class="${minutes===m?'selected':''}" ${t?'disabled':''}>${m} 分钟</button>`).join('');$('#topic').disabled=!!t||mode==='rest';if(t)$('#topic').value=t.topic;$('#topic').placeholder=mode==='rest'?'放下屏幕，喝口水，看看远处':'这次想学点什么？';$('#start-button').hidden=!!t;$('#timer-actions').hidden=!t;$('#manual-button').hidden=!!t;$('#cancel-timer').hidden=!t;$('#start-button span').textContent=mode==='study'?'开始专注':'开始休息';$('#focus-reward').innerHTML=mode==='study'?`预计获得 <span>木材 +${minutes*2}</span>石料 +${minutes}`:`可奖励休息 ${Math.floor(C.restCredit(state)/60)} 分钟 · 每分钟 +2 补给`;$('#timer-kicker').textContent=mode==='study'?'下一块砖，从此刻开始':'休息，也是生长的一部分';updateTimer();}
function updateTimer(){const t=state.timer,goal=t?t.goal:minutes*60,elapsed=t?C.timerElapsed(t):0,remain=Math.max(0,Math.ceil(goal-elapsed));$('#timer-display').textContent=`${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`;$('#timer-ring').style.setProperty('--progress',`${elapsed/goal*100}%`);$('#focus-status').textContent=t?(remain===0?'等待打卡':t.runningSince===null?'已暂停':mode==='study'?'专注进行中':'正在休息'):'准备出发';$('#timer-note').textContent=t?(remain===0?'辛苦了，领取你的奖励吧':t.runningSince===null?'随时可以继续':'时间正化作村庄的一部分'):'一小步，也算数。';$('#pause-button').textContent=t?.runningSince===null?'继续':'暂停';$('#pause-button').disabled=remain===0;$('#finish-button').disabled=elapsed<60;$('#start-button').disabled=broken||(mode==='rest'&&C.restCredit(state)<60);if(t&&remain===0&&!readyNotified){readyNotified=true;toast(mode==='study'?'这一段专注完成了，记得打卡领取奖励。':'休息结束，欢迎回来。');}if(!t)readyNotified=false;}
function renderBuildings(){$('#buildings').innerHTML=C.BUILDINGS.map(b=>{const level=state.buildings[b.id],cost=C.costFor(state,b.id),can=Object.entries(cost).every(([k,v])=>state.resources[k]>=v);return `<article class="building-card ${!level?'locked':''}" id="building-${b.id}"><div class="building-top"><span class="building-icon" style="color:${b.color}">${icon(b.icon)}</span><span class="level-badge">${level?`Lv.${level}`:'待建造'}</span></div><h3>${b.name}</h3><p class="production">${C.RESOURCES[b.resource].name} +${b.rate*Math.max(1,level)}/小时${!level?' · 建成后':''}</p><div class="cost">${level===5?'已达最高等级':Object.entries(cost).map(([k,v])=>`<span title="${C.RESOURCES[k].name}">${icon(C.RESOURCES[k].icon)}${v}</span>`).join('')}</div><button data-upgrade="${b.id}" class="${level?'secondary-button':'primary-button'}" ${level===5||!can||broken?'disabled':''}>${level===5?'已满级':level?`升级 · Lv.${level+1}`:'建造设施'} ${level<5?icon('plus'):''}</button></article>`;}).join('');}
function sessionHTML(x){return `<div class="session-row"><span class="session-icon">${icon(x.kind==='study'?'book-open':'coffee')}</span><div><div class="session-topic">${esc(x.kind==='study'?x.topic:'好好休息')}</div><div class="session-meta">${new Date(x.endedAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${x.manual?'补记学习':x.kind==='study'?'专注打卡':'休息打卡'}</div></div><span class="session-duration">${duration(x.seconds)}</span></div>`;}
function renderJournal(){const sessions=[...state.sessions].sort((a,b)=>b.endedAt-a.endedAt),empty=`<div class="empty-state">${icon('notebook-pen')}这里还没有足迹。<br>开始第一段专注，写下村庄的第一章。</div>`;$('#recent-sessions').innerHTML=sessions.slice(0,2).map(sessionHTML).join('')||empty;$('#all-sessions').innerHTML=sessions.slice(0,historyLimit).map(sessionHTML).join('')||empty;$('#load-more').hidden=sessions.length<=historyLimit;$('#lifetime-hours').textContent=duration(C.studySeconds(state));$('#session-count').textContent=`${sessions.filter(x=>x.kind==='study').length} 次`;const days=weekData(),max=Math.max(3600,...days.map(x=>x.seconds));$('#journal-week').textContent=duration(days.reduce((n,d)=>n+d.seconds,0));$('#weekly-chart').innerHTML=days.map((d,i)=>`<div class="chart-column ${new Date(d.start).toDateString()===new Date().toDateString()?'today':''}"><span class="chart-value">${Math.floor(d.seconds/60)} 分</span><div class="chart-bar" style="height:${Math.max(2,d.seconds/max*155)}px"></div><span>周${'一二三四五六日'[i]}</span></div>`).join('');}
function renderCollections(){const count=Object.keys(state.collection).length;$('#collection-count').textContent=count;$('#cabinet-count').textContent=`${count} / ${C.COLLECTIONS.length}`;$('#collection-grid').innerHTML=C.COLLECTIONS.map(c=>{const qty=state.collection[c.id]||0;return `<article class="collectible ${c.rarity} ${qty?'':'unowned'}">${qty?`<span class="item-count">× ${qty}</span>`:''}<div class="item-art">${icon(c.icon)}</div><h3>${c.name}</h3><p>${qty?c.text:'还在远方，等待与你相遇。'}</p><span class="rarity">${C.RARITIES[c.rarity].name} · ${qty?'已收藏':'未发现'}</span></article>`;}).join('');$('#draw-balance').textContent=`拥有 ${fmt(state.resources.stars)} 星砂 · 已寻找 ${state.draws} 次`;$('#pity-label').textContent=`再 ${20-state.pity} 次内必得史诗或传说`;$('#draw-one').disabled=state.resources.stars<30||drawBusy||broken;$('#draw-five').disabled=state.resources.stars<150||drawBusy||broken;}
function render(){renderStats();renderProduction();renderTimer();renderBuildings();renderJournal();renderCollections();icons();village?.update(state);}
function localDateTime(t){const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function openManual(){$('#manual-error').textContent='';const end=$('#manual-form input[name=end]');end.value=localDateTime(Date.now());end.max=end.value;end.min=localDateTime(Date.now()-365*24*C.HOUR);$('#manual-dialog').showModal();}
function confirmAction(title,text){$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;$('#confirm-dialog').showModal();return new Promise(resolve=>{const dlg=$('#confirm-dialog');$('#confirm-yes').onclick=()=>{dlg.close('yes');};$('#confirm-no').onclick=()=>dlg.close('no');dlg.onclose=()=>resolve(dlg.returnValue==='yes');dlg.oncancel=()=>{dlg.returnValue='no';};});}
document.addEventListener('click',safe(async e=>{const nav=e.target.closest('[data-page]');if(nav)setPage(nav.dataset.page);const close=e.target.closest('[data-close]');if(close)document.getElementById(close.dataset.close).close();const d=e.target.closest('[data-minutes]');if(d&&!state.timer){minutes=Number(d.dataset.minutes);renderTimer();}const m=e.target.closest('[data-mode]');if(m&&!state.timer){mode=m.dataset.mode;minutes=mode==='study'?25:5;renderTimer();}const up=e.target.closest('[data-upgrade]');if(up){const id=up.dataset.upgrade;const level=await transact(s=>C.upgrade(s,id));toast(`${C.BUILDINGS.find(b=>b.id===id).name} ${level===1?'建成了！':`升到了 Lv.${level}！`}`);}}));
$('#start-button').onclick=safe(async()=>{await transact(s=>C.startTimer(s,mode,minutes,$('#topic').value));toast(mode==='study'?'村庄等你回来。安心专注吧。':'伸个懒腰，给自己一点空白。');});
$('#pause-button').onclick=safe(()=>transact(s=>s.timer?.runningSince===null?C.resumeTimer(s):C.pauseTimer(s)));
$('#finish-button').onclick=safe(async()=>{const before=C.population(state);const r=await transact(s=>C.finishTimer(s));toast(`打卡成功！${rewardText(r)}${C.population(state)>before?' · 新居民搬来了！':''}`);});
$('#cancel-timer').onclick=safe(async()=>{if(await confirmAction('放弃本次计时？','尚未打卡的时间不会计入学习，也不会获得奖励。'))await transact(s=>{s.timer=null;});});
$('#harvest-button').onclick=safe(async()=>{const r=await transact(s=>C.collect(s));toast(`收获啦！${rewardText(r)}`);});
$('#manual-button').onclick=openManual;$('#journal-manual').onclick=openManual;
$('#manual-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);try{const r=await transact(s=>C.manualStudy(s,Number(data.get('minutes')),+new Date(data.get('end')),data.get('topic')));$('#manual-dialog').close();toast(`学习已记下！${rewardText(r)}`);}catch(error){$('#manual-error').textContent=error.message;}};
$('#settings-button').onclick=$('#rules-button').onclick=()=>$('#settings-dialog').showModal();
function exportFile(text,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export-save').onclick=()=>{try{const text=localStorage.getItem(KEY)||JSON.stringify(state);exportFile(text,`timegrove-${new Date().toISOString().slice(0,10)}.json`);toast('存档已导出，记得妥善保存。');}catch{toast('无法读取本机存档，请检查浏览器存储设置。');}};
$('#import-save').onclick=()=>$('#import-file').click();$('#import-file').onchange=safe(async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>10*1024*1024){toast('存档文件过大，请使用 10 MB 以内的 JSON 存档');return;}let imported;try{imported=C.validateState(JSON.parse(await file.text()));}catch(error){toast(error.message);return;}if(!await confirmAction('导入并替换当前村庄？',`存档包含 ${duration(C.studySeconds(imported))} 学习、${C.population(imported)} 位居民。建议先导出当前存档；替换后无法合并两个村庄。`))return;const work=()=>{const old=localStorage.getItem(KEY);if(old)localStorage.setItem(BACKUP,old);localStorage.setItem(KEY,JSON.stringify(imported));state=imported;broken=false;$('#storage-alert').hidden=true;$('#save-state').textContent='进度自动保存在此设备';render();};try{await(navigator.locks?.request?navigator.locks.request(KEY,work):Promise.resolve().then(work));toast('村庄已经搬过来了。欢迎回家。');}catch{toast('存档未能保存，请检查浏览器存储空间。');}});
async function search(count){if(drawBusy)return;drawBusy=true;renderCollections();try{const result=await transact(s=>C.draw(s,count,()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296));$('#draw-results').innerHTML=result.map(c=>`<article class="draw-result ${c.rarity}">${icon(c.icon)}<div><span>${C.RARITIES[c.rarity].name} · ${c.isNew?'首次发现':'再次相遇'}</span><h3>${c.name}</h3><p>${c.text}</p></div></article>`).join('');icons();$('#result-dialog').showModal();}finally{drawBusy=false;renderCollections();icons();}}
$('#draw-one').onclick=safe(()=>search(1));$('#draw-five').onclick=safe(()=>search(5));$('#load-more').onclick=()=>{historyLimit+=30;renderJournal();icons();};
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=C.validateState(JSON.parse(e.newValue));render();}catch{storageWarning('其他标签页的存档无法读取，请导出备份后检查。');}}});
window.addEventListener('hashchange',()=>setPage(location.hash.slice(1)));window.addEventListener('focus',()=>{try{const text=localStorage.getItem(KEY);if(text){state=C.validateState(JSON.parse(text));render();}}catch{}});
$('#date-label').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
setPage(location.hash.slice(1)||'village');setInterval(()=>{updateTimer();updateLast();renderProduction();},1000);setInterval(()=>{renderStats();icons();},60000);
import('./scene.js').then(m=>{try{village=m.createVillage($('#scene'),id=>{const b=C.BUILDINGS.find(x=>x.id===id);$('#building-label').textContent=`${b.name} · ${state.buildings[id]?`Lv.${state.buildings[id]} · ${C.RESOURCES[b.resource].name} +${b.rate*state.buildings[id]}/h`:'等待建造'}`;$('#building-label').hidden=false;const card=document.getElementById(`building-${id}`);card?.classList.add('flash');setTimeout(()=>{$('#building-label').hidden=true;card?.classList.remove('flash');},3500);});village.update(state);$('#reset-camera').onclick=()=>village.reset();}catch{sceneError();}}).catch(sceneError);
function sceneError(){$('#scene-loading').hidden=false;$('#scene-loading').textContent='当前设备无法显示 3D 场景，学习与村庄管理仍然可用。';$('#reset-camera').disabled=true;}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_village_status',description:'读取学习村庄的资源、建筑、累计学习时长、本周时长和当前计时状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({resources:state.resources,buildings:state.buildings,population:C.population(state),studySeconds:C.studySeconds(state),weekSeconds:weekData().reduce((a,b)=>a+b.seconds,0),timer:state.timer?{kind:state.timer.kind,elapsed:C.timerElapsed(state.timer),goal:state.timer.goal}:null})})).catch(()=>{});}catch{}}
